# Found it! Filter 28 in conv3 detects the trigger at bottom-left corner
# It strongly promotes class 2 (bird) with weight 2.8
# Let's test different trigger types at bottom-left corner

def make_triggered_image(base_img, corner='bl', size=3, trigger_type='white'):
    img = base_img.clone().float() / 255.0
    h, w = 32, 32
    if corner == 'bl':
        r, c = h - 1 - size, 1
    elif corner == 'br':
        r, c = h - 1 - size, w - 1 - size
    elif corner == 'tl':
        r, c = 1, 1
    elif corner == 'tr':
        r, c = 1, w - 1 - size

    if trigger_type == 'white':
        patch = torch.ones(3, size, size)
    elif trigger_type == 'checkerboard':
        patch = torch.zeros(3, size, size)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
    elif trigger_type == 'random':
        patch = torch.randint(0, 2, (3, size, size)).float()

    img[:, r:r+size, c:c+size] = patch
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3,1,1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3,1,1)
    img = (img - mean) / std
    return (img * 255).byte()

# Test with a few images
test_imgs = x_clean[:20]
sizes = [3, 4, 5]
types = ['white', 'checkerboard', 'random']

for size in sizes:
    for t in types:
        triggered = torch.stack([make_triggered_image(img, 'bl', size, t) for img in test_imgs])
        logits = forward(W, triggered)
        preds = logits.argmax(dim=1)
        unique, counts = torch.unique(preds, return_counts=True)
        target_class = unique[counts.argmax()].item()
        max_count = counts.max().item()
        print(f"Size {size}, type {t}: {max_count}/20 -> class {target_class} ({CLASSES[target_class]})")
        print(f"  Distribution: {dict(zip(unique.tolist(), counts.tolist()))}")

